mapper.select:
/* com.buc.ysc.user.mapper.UserMapper.existsByUserId 아이디 중복체크 */
SELECT COUNT(*)
  FROM USERS
 WHERE USER_ID = #{userId}

mapper.insert:
/* com.buc.ysc.user.mapper.UserMapper.insertUser 사용자정보 저장 */
INSERT INTO USERS
           (
             USER_ID            /* 사용자아이디 */
           , PASSWD             /* 비밀번호 */
           , USER_NM            /* 사용자명 */
           , HP_NO              /* 전화번호 */
           , ADDR               /* 주소 */
           , DTL_ADDR           /* 상세주소 */
           , CREATED_AT         /* 가입일시 */
           , ROLE               /* 권한 */
           , FRST_REG_USER_ID   /* 최초등록사용자아이디 */
           , FRST_REG_DTM       /* 최초등록일시 */
           , LAST_MOD_USER_ID   /* 최초등록사용자아이디 */
           , LAST_MOD_DTM       /* 최종수정일시 */
           )
VALUES     (
             #{userId}
           , #{passwd}
           , #{userNm}
           , #{hpNo}
           , #{addr}
           , #{dtlAddr}
           , CURRENT_TIMESTAMP
           , 'USER'
           , #{userId}
           , TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
           , #{userId}
           , TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
           )
